package net.civeira.phylax.features.oauth.tokensecurity.infrastructure.driver.rest;

import java.nio.charset.StandardCharsets;
import java.util.Base64;

import jakarta.enterprise.context.RequestScoped;
import jakarta.ws.rs.Consumes;
import jakarta.ws.rs.POST;
import jakarta.ws.rs.Path;
import jakarta.ws.rs.PathParam;
import jakarta.ws.rs.core.Context;
import jakarta.ws.rs.core.HttpHeaders;
import jakarta.ws.rs.core.MediaType;
import jakarta.ws.rs.core.MultivaluedMap;
import jakarta.ws.rs.core.Response;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.features.oauth.client.domain.gateway.ClientStoreGateway;
import net.civeira.phylax.features.oauth.tokensecurity.application.usecase.RevokeTokenUseCase;

/**
 * REST controller for the RFC 7009 token revocation endpoint.
 *
 * Responsibilities: - Authenticate the requesting client (client_secret_basic or
 * client_secret_post). - Delegate revocation logic to {@link RevokeTokenUseCase}. - Always respond
 * HTTP 200 with Cache-Control: no-store.
 *
 * Design notes: - Per RFC 7009 §2.2, the response is always 200 OK regardless of whether the token
 * was valid. Callers cannot infer token existence from the response. - Client authentication
 * failure is the only case that returns non-200.
 */
@Path("")
@RequestScoped
@RequiredArgsConstructor
public class TokenRevocationController {

  private final RevokeTokenUseCase revokeTokenUseCase;
  private final ClientStoreGateway clientRetriever;

  /**
   * Revokes a token submitted by a client.
   *
   * Authenticates the client via HTTP Basic Auth (client_secret_basic) or form parameters
   * (client_secret_post). Delegates revocation to the use case; invalid or unparseable tokens are
   * silently accepted per RFC 7009.
   *
   * @param tenant tenant identifier from the path
   * @param headers HTTP request headers (Authorization)
   * @param paramMap form parameters (token, token_type_hint, client_id, client_secret)
   * @return 200 with no body on success, 401 when client credentials are missing or invalid
   */
  @POST
  @Path("oauth/openid/{tenant}/revocation")
  @Consumes(MediaType.APPLICATION_FORM_URLENCODED)
  public Response revoke(final @PathParam("tenant") String tenant,
      final @Context HttpHeaders headers, final MultivaluedMap<String, String> paramMap) {

    String clientId = null;
    String clientSecret = null;

    String authHeader = headers.getHeaderString(HttpHeaders.AUTHORIZATION);
    if (authHeader != null && authHeader.startsWith("Basic ")) {
      String decoded = new String(Base64.getDecoder().decode(authHeader.substring(6).getBytes()),
          StandardCharsets.UTF_8);
      String[] parts = decoded.split(":", 2);
      if (parts.length == 2 && !parts[0].isBlank()) {
        clientId = parts[0];
        clientSecret = parts[1];
      }
    }

    if (clientId == null) {
      clientId = paramMap.getFirst("client_id");
      clientSecret = paramMap.getFirst("client_secret");
    }

    if (clientId == null || clientId.isBlank()) {
      return Response.status(401).build();
    }

    String secret = clientSecret != null ? clientSecret : "";
    if (clientRetriever.loadPrivate(tenant, clientId, secret).isEmpty()) {
      return Response.status(401).build();
    }

    String rawToken = paramMap.getFirst("token");
    String tokenTypeHint = paramMap.getFirst("token_type_hint");
    revokeTokenUseCase.revoke(tenant, rawToken, tokenTypeHint);

    return Response.ok().header("Cache-Control", "no-store").build();
  }
}
